'use strict';
const {Network,sample,shift,dataset,score,rng}=DigitLab;
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
let net=null,hiddenSize=16,baseline=null,x=sample(3),neuron=0,pixel=2,recognized=false,busy=false,draw=false,paint=1,random=rng(781),animation=0;
const fixed=n=>n.toFixed(4),signed=n=>(n>=0?'+':'−')+Math.abs(n).toFixed(4);
for(let i=0;i<10;i++){for(const id of ['#example','#truth']){const o=document.createElement('option');o.value=i;o.textContent=i;$(id).append(o);}}$('#example').value='3';
for(let i=0;i<64;i++){const b=document.createElement('button');b.className='pixel';b.type='button';b.dataset.i=i;b.setAttribute('aria-label',`Клетка ${Math.floor(i/8)+1}, ${i%8+1}`);b.addEventListener('pointerdown',e=>{if(busy)return;e.preventDefault();draw=true;paint=x[i]>.5?0:1;x[i]=paint;changed();});b.addEventListener('click',e=>{if(e.detail===0&&!busy){x[i]=x[i]>.5?0:1;changed();}});$('#drawing').append(b);const m=document.createElement('i');$('#mini-input').append(m);}
window.addEventListener('pointerup',()=>draw=false);window.addEventListener('pointercancel',()=>draw=false);
$('#drawing').addEventListener('pointermove',e=>{if(!draw||busy)return;e.preventDefault();const t=document.elementFromPoint(e.clientX,e.clientY);if(t?.classList.contains('pixel')){x[+t.dataset.i]=paint;changed();}});
function buildNeurons(){$('#neurons').innerHTML='';for(let j=0;j<hiddenSize;j++){const b=document.createElement('button');b.className='neuron';b.textContent=j+1;b.setAttribute('aria-label',`Выбрать нейрон ${j+1}`);b.onclick=()=>{neuron=j;renderInside();};$('#neurons').append(b);}
}
for(let i=0;i<64;i++){const b=document.createElement('button');b.onclick=()=>{pixel=i;renderInside();};$('#weights').append(b);}
function paintInput(){ $$('.pixel').forEach((b,i)=>{b.style.background=`rgb(${24+Math.round(x[i]*201)},${60+Math.round(x[i]*178)},${58+Math.round(x[i]*161)})`;b.setAttribute('aria-pressed',x[i]>.5);});$$('#mini-input i').forEach((m,i)=>m.style.opacity=.12+.88*x[i]);}
function changed(){recognized=false;clearTimeout(animation);paintInput();$('#answer').innerHTML='—';$('#bars').innerHTML='';$('#stale').textContent='Рисунок изменён. Нажми «Распознать», чтобы получить новый ответ.';$('#formula').textContent='Рисунок изменён — сначала распознай его';$('#activation').textContent='Новые значения появятся после распознавания.';$('#truth').value='';$('#learning-change').textContent='Укажи правильную цифру для нового рисунка.';$('#gradient-detail').textContent='';renderInside();}
function renderInside(){if(!net)return;const f=net.forward(x);$$('.pixel').forEach((b,i)=>b.classList.toggle('chosen',i===pixel&&recognized));$$('.neuron').forEach((b,j)=>{b.classList.toggle('selected',j===neuron);b.style.background=recognized?`rgba(20,125,112,${.08+.65*Math.abs(f.h[j])})`:'#edf3ee';b.title=recognized?`Выход: ${fixed(f.h[j])}`:'Сначала распознай рисунок';});$('#neuron-title').textContent=`Нейрон ${neuron+1}: один расчёт под лупой`;if(recognized){const sum=f.z[neuron]-net.b1[neuron];$('#formula').innerHTML=`${fixed(sum)} ${signed(net.b1[neuron])} = ${fixed(f.z[neuron])}<br><small>сумма 64 произведений + смещение</small>`;$('#activation').textContent=`Выход нейрона: tanh(${fixed(f.z[neuron])}) = ${fixed(f.h[neuron])}. Это число передаётся всем 10 выходным нейронам.`;}$$('#weights button').forEach((b,i)=>{const w=net.w1[neuron][i];b.textContent=w.toFixed(2);b.style.background=w>=0?`rgba(20,125,112,${Math.min(.65,.1+Math.abs(w)*.5)})`:`rgba(185,92,48,${Math.min(.6,.1+Math.abs(w)*.5)})`;b.classList.toggle('chosen',i===pixel);b.setAttribute('aria-label',`Клетка ${i+1}, вес ${fixed(w)}`);});$('#weight-calculation').innerHTML=`${fixed(x[pixel])} × ${fixed(net.w1[neuron][pixel])} = ${fixed(x[pixel]*net.w1[neuron][pixel])}<br><small>клетка ${pixel+1} × её вес = вклад в сумму</small>`;}
function recognize(animate=true){if(!net)return;recognized=true;if(animate){pixel=x.reduce((best,v,i)=>Math.abs(v*net.w1[neuron][i])>Math.abs(x[best]*net.w1[neuron][best])?i:best,0);}const f=net.forward(x),best=f.p.indexOf(Math.max(...f.p));$('#answer').innerHTML=`${best} <small>предположение сети</small>`;$('#bars').innerHTML=f.p.map((p,k)=>`<div class="bar-row ${k===best?'winner':''}"><span>${k}</span><div class="track"><div class="fill" style="width:${p*100}%"></div></div><span>${(p*100).toFixed(1)}%</span></div>`).join('');$('#stale').textContent=x.every(v=>v===0)?'Поле пустое. Это не осмысленная цифра, но сеть всё равно распределила оценки между 10 классами.':'Оценки вычислены для текущего рисунка. Веса при распознавании не менялись.';renderInside();if(animate){const blocks=[$('#mini-input'),$('#neurons'),$('#answer')];blocks.forEach(b=>b.classList.remove('pulse'));let i=0;const next=()=>{if(i>=blocks.length)return;blocks[i++].classList.add('pulse');animation=setTimeout(next,550);};clearTimeout(animation);next();} }
$('#recognize').onclick=()=>{recognize();setStep(1,false);};
$('#example').onchange=()=>{x=sample(+$('#example').value);changed();};$('#clear').onclick=()=>{x=Array(64).fill(0);changed();};$('#shift').onclick=()=>{x=shift(x,1,0);changed();};$('#noise').onclick=()=>{x=x.map(v=>random()<.10?1-v:v);changed();};
function measure(before,after){$('#metric-before').textContent='До действия: верных ответов';$('#metric-after').textContent='После действия: верных ответов';$('#score-before').textContent=`${before} / 60`;$('#score-after').textContent=`${after} / 60`;if(baseline!==null){$('#journey-baseline').textContent=baseline+' / 60';$('#journey-now').textContent=after+' / 60';}}
$('#train-one').onclick=()=>{if(busy)return;const v=$('#truth').value;if(v===''){$('#learning-change').textContent='Выбери правильную цифру в поле выше. Сеть не знает её без твоей подсказки.';$('#truth').focus();return;}if(x.every(v=>v===0)){$('#learning-change').textContent='Сначала нарисуй цифру или выбери готовый пример. Пустое поле не будем выдавать за цифру.';return;}const beforeScore=score(net);const r=net.train(x,+v);neuron=0;let best=0;for(let i=1;i<64;i++)if(Math.abs(net.w1[0][i]-r.before[i])>Math.abs(net.w1[0][best]-r.before[best]))best=i;pixel=best;recognize(false);measure(beforeScore,score(net));$('#learning-change').innerHTML=`Ошибка на этом рисунке: <b>${fixed(r.loss)} → ${fixed(r.afterLoss)}</b>.<br>Нейрон 1, вес клетки ${pixel+1}: <b>${fixed(r.before[pixel])} → ${fixed(net.w1[0][pixel])}</b>.<br>Один шаг не гарантирует улучшения на остальных рисунках.`;$('#gradient-detail').textContent=`Для выбранного изменения: ${fixed(r.before[pixel])} − ${r.rate} × ${fixed(r.dh*x[pixel])} = ${fixed(net.w1[0][pixel])}.`;$('#model-state').textContent=`Весá изменены по твоей подсказке. Всего шагов обучения: ${net.steps}.`;};
function setBusy(v){busy=v;$$('button,select').forEach(b=>b.disabled=v);}
async function trainSet(diverse){if(busy)return;setBusy(true);const before=score(net);net=new Network(42,hiddenSize);const data=dataset(diverse),r=rng(431);for(let i=0;i<4000;i++){const t=data[Math.floor(r()*data.length)];net.train(t.x,t.y);if(i%250===0){$('#model-state').textContent=`Обучение: ${i} / 4000 шагов…`;await new Promise(resolve=>setTimeout(resolve,0));}}setBusy(false);measure(before,score(net));$('#metric-before').textContent='Предыдущая сеть: верных';$('#metric-after').textContent='Новая сеть: верных';$('#model-state').textContent=`Обучено на ${data.length} учебных примерах. Выполнено 4000 шагов. Данные ${diverse?'включают сдвиги':'содержат только исходные шаблоны'}.`;$('#learning-change').textContent='Сеть переобучена с исходных случайных весов. Теперь можно сделать отдельный шаг на своём рисунке.';$('#gradient-detail').textContent='';recognize();}
$('#train-base').onclick=()=>trainSet(false);$('#train-rich').onclick=()=>trainSet(true);$('#reset').onclick=()=>{const before=score(net);net=new Network(42,hiddenSize);measure(before,score(net));$('#model-state').textContent='Обучение сброшено. Веса случайные: сеть ещё не училась распознавать цифры.';$('#learning-change').textContent='После сброса можно обучить сеть на наборе примеров или на своём рисунке.';$('#gradient-detail').textContent='';recognize(false);};
const instructions=[['Начни с одного нажатия','Выбери пример или нарисуй цифру. Нажми «Распознать». Сеть использует веса, но не меняет их.'],['Проследи один расчёт','Выбери круглый нейрон. Раскрой «Покажи веса» и нажми на клетку: вход × вес даёт вклад в сумму.'],['Исправь и проверь','Укажи правильную цифру и сделай шаг обучения. Сравни ошибку на рисунке и число верных ответов на новых примерах.']];
function setStep(i,scroll=true){$$('[data-step]').forEach(b=>b.classList.toggle('active',+b.dataset.step===i));$('#instruction').innerHTML=`<b>${instructions[i][0]}</b>${instructions[i][1]}`;if(i===1&&scroll)$('#weights-details').open=true;if(scroll)(i===2?$('#train-card'):i===1?$('#inside-card'):$('#drawing')).scrollIntoView({behavior:'smooth',block:'center'});}
$$('[data-step]').forEach(b=>b.onclick=()=>setStep(+b.dataset.step));
paintInput();window.labDebug={get net(){return net;},get input(){return x;}};

function createNetwork(){
 hiddenSize=+$('#hidden-size').value;net=new Network(42,hiddenSize);neuron=0;pixel=2;recognized=false;baseline=score(net);buildNeurons();
 $('#experience').hidden=false;$('#builder-status').textContent=`Сеть 64 → ${hiddenSize} → 10 создана. Обучение ещё не запускалось.`;
 $('#hidden-count').textContent=hiddenSize+' нейронов';$('#network-count').textContent=`Сеть содержит ${74*hiddenSize} весов и ${hiddenSize+10} смещений. Это реальные параметры модели.`;
 $('#architecture-note').textContent=`Текущая архитектура: 64 → ${hiddenSize} → 10, tanh и softmax.`;
 $('#model-state').textContent='Сеть создана со случайными весами. Пока она не училась. Даже верный ответ на одну цифру может быть случайным.';
 $('#create-network').textContent='Создать заново без обучения';$('#hidden-size').dataset.applied=hiddenSize;
 $('#gradient-detail').textContent='';changed();measure(baseline,baseline);$('#metric-before').textContent='Без обучения: верных';$('#metric-after').textContent='Сейчас: верных';
 setStep(0,false);$('#instruction').innerHTML='<b>Сеть создана. Проверь её до обучения</b>Нажми «Распознать». Пока веса случайные. Затем раскрой один расчёт и переходи к обучению.';
 $('#journey-note').textContent='Сохраняем результат новой необученной сети. После обучения сравним с ним на тех же 60 контрольных рисунках.';
 startAssembly();
}
$('#create-network').onclick=createNetwork;
$('#hidden-size').onchange=()=>{$('#builder-status').textContent=net?'Выбран новый размер. Он применится после «Создать заново»: текущее обучение будет сброшено.':'Выбери размер скрытого слоя и нажми «Создать сеть».';};
